import{_ as t,o as d,c as e,Q as a}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"Chef Job Application (Textbook Writing Template)","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/17-chef-job-application-template.md","filePath":"en/more/maltese/practice/emails/17-chef-job-application-template.md"}'),r={name:"en/more/maltese/practice/emails/17-chef-job-application-template.md"},o=a('<h1 id="chef-job-application-textbook-writing-template" tabindex="-1">Chef Job Application (Textbook Writing Template) <a class="header-anchor" href="#chef-job-application-textbook-writing-template" aria-label="Permalink to &quot;Chef Job Application (Textbook Writing Template)&quot;">​</a></h1><p><strong>Scenario:</strong> An applicant writes to a restaurant to apply for the position of chef. This is the original textbook template from the PDF, including the gap-fill options in brackets. Note: the closing is printed <code>Tisjiet</code> in the source; the standard formal spelling is <code>Tislijiet</code>.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand (From):</strong> gorg.com.mt <strong>Data (Date):</strong> 16 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand:</strong> gorg.com.mt <strong>Data:</strong> 16 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p>Għażiż Sinjur / Sinjura</p><p>Jien qiegħed nibgħatlek din l-ittra biex (napplika / tapplika) għal xogħol.</p><p>Nispera li tinsab tajjeb. Qed nibgħatlek din l-ittra elettronika sabiex napplika għal xogħol ta&#39; kok fir-restorant tiegħek.</p><p>Jien nixtieq naħdem bħala kok għax inħobb insajjar, inħobb naħdem ma&#39; ħaddieħor u nħobb niltaqa&#39; man-nies.</p><p>Kont immur l-iskola tal-ITS (institute of tourism studies) u minn hemm ġibt iċ-ċertifikati li kelli bżonn. Għandi esperjenza ta&#39; ħames snin naħdem f&#39;restorant ta&#39; lukanda lussuża.</p><p>u għalhekk naħseb li kapaċi għal dan ix-xogħol. Naf nitkellem Ingliż, Malti, u ftit Taljan.</p><p>Grazzi talli qrajt din l-ittra. Napprezza jekk tikkunsidrani għal dan ix-xogħol.</p><p>Nista&#39; niltaqa&#39; miegħek biex nikkellmu iktar fid-dettall kuljum mit-8 ta&#39; filgħodu sas-7 ta&#39; filgħaxija. / meta tkun komdu inti.</p><p>Tisjiet, John Mallia</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></td><td>email address</td><td>The restaurant&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: gorg.com.mt</p><p><strong>Translation:</strong> From: gorg.com.mt</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field</td></tr><tr><td>gorg.com.mt</td><td>email address</td><td>Example sender address (Gorg)</td></tr></tbody></table><p><strong>Malti:</strong> Data: 16 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 16 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field</td></tr><tr><td>16</td><td>sixteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p><strong>Translation:</strong> Subject: Job Application for a Chef</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>kok</td><td>chef; cook</td><td>Loanword <code>cook</code></td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura</p><p><strong>Translation:</strong> Dear Sir / Madam</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular adjective</td></tr><tr><td>Sinjur</td><td>Sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Choice marker</td></tr><tr><td>Sinjura</td><td>Madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Jien qiegħed nibgħatlek din l-ittra biex (napplika / tapplika) għal xogħol.</p><p><strong>Translation:</strong> I am sending you this letter to (apply / you apply) for a job.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person pronoun</td></tr><tr><td>qiegħed</td><td>am (progressive)</td><td>Progressive marker, masculine</td></tr><tr><td>nibgħatlek</td><td>I send you</td><td><code>nibgħat</code> + <code>-lek</code> (to you)</td></tr><tr><td>din l-ittra</td><td>this letter</td><td><code>din</code> (this) + <code>ittra</code> (letter)</td></tr><tr><td>biex</td><td>in order to</td><td>Purpose conjunction</td></tr><tr><td>napplika</td><td>I apply</td><td>Gap-fill option 1: loanword <code>apply</code>, first person</td></tr><tr><td>tapplika</td><td>you apply</td><td>Gap-fill option 2: second person</td></tr><tr><td>għal xogħol</td><td>for a job</td><td><code>għal</code> (for) + <code>xogħol</code> (job)</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tinsab tajjeb. Qed nibgħatlek din l-ittra elettronika sabiex napplika għal xogħol ta&#39; kok fir-restorant tiegħek.</p><p><strong>Translation:</strong> I hope you are well. I am sending you this email to apply for the position of chef in your restaurant.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular</td></tr><tr><td>li</td><td>that</td><td>Conjunction</td></tr><tr><td>tinsab</td><td>you are</td><td>Second-person form of <code>tinsab</code></td></tr><tr><td>tajjeb</td><td>well</td><td>Adverb/adjective</td></tr><tr><td>Qed</td><td>am (progressive)</td><td>Progressive marker</td></tr><tr><td>nibgħatlek</td><td>I send you</td><td>See above</td></tr><tr><td>din l-ittra elettronika</td><td>this email</td><td><code>ittra</code> + <code>elettronika</code></td></tr><tr><td>sabiex</td><td>in order to</td><td>Formal conjunction</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular</td></tr><tr><td>għal xogħol ta&#39; kok</td><td>for a chef&#39;s job</td><td><code>kok</code> (chef)</td></tr><tr><td>fir-restorant</td><td>in the restaurant</td><td>Contracted <code>f&#39;</code> + <code>ir-restorant</code></td></tr><tr><td>tiegħek</td><td>your</td><td>Masculine possessive</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jien nixtieq naħdem bħala kok għax inħobb insajjar, inħobb naħdem ma&#39; ħaddieħor u nħobb niltaqa&#39; man-nies.</p><p><strong>Translation:</strong> I want to work as a chef because I love cooking, I love working with others, and I love meeting people.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>Pronoun</td></tr><tr><td>nixtieq</td><td>I want</td><td>First-person singular</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular</td></tr><tr><td>bħala</td><td>as</td><td>Preposition</td></tr><tr><td>kok</td><td>chef</td><td>Loanword</td></tr><tr><td>għax</td><td>because</td><td>Causal conjunction</td></tr><tr><td>inħobb</td><td>I love</td><td>First-person singular</td></tr><tr><td>insajjar</td><td>I cook</td><td>First-person singular</td></tr><tr><td>ma&#39; ħaddieħor</td><td>with others</td><td><code>ħaddieħor</code> (someone else / others)</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>niltaqa&#39;</td><td>I meet</td><td>First-person singular</td></tr><tr><td>man-nies</td><td>with people</td><td>Contracted <code>ma&#39;</code> + <code>in-nies</code></td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Kont immur l-iskola tal-ITS (institute of tourism studies) u minn hemm ġibt iċ-ċertifikati li kelli bżonn.</p><p><strong>Translation:</strong> I used to attend the ITS school (Institute of Tourism Studies) and from there I got the certificates I needed.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Kont</td><td>I used to</td><td>Past auxiliary</td></tr><tr><td>immur</td><td>I go</td><td>First-person singular</td></tr><tr><td>l-iskola</td><td>the school</td><td>Feminine noun with the definite article</td></tr><tr><td>tal-ITS</td><td>of the ITS</td><td>Contracted <code>ta&#39;</code> + <code>l-ITS</code></td></tr><tr><td>minn hemm</td><td>from there</td><td>Place phrase</td></tr><tr><td>ġibt</td><td>I got; I brought</td><td>First-person singular past</td></tr><tr><td>iċ-ċertifikati</td><td>the certificates</td><td>Plural of <code>ċertifikat</code> with the definite article</td></tr><tr><td>li</td><td>that; which</td><td>Relative pronoun</td></tr><tr><td>kelli bżonn</td><td>I needed</td><td><code>kell</code> (had) + <code>bżonn</code> (need)</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; ħames snin naħdem f&#39;restorant ta&#39; lukanda lussuża.</p><p><strong>Translation:</strong> I have five years&#39; experience working in a luxury hotel restaurant.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular of <code>għand</code></td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>ta&#39; ħames snin</td><td>of five years</td><td><code>ħames</code> (five) + <code>snin</code> (years)</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular</td></tr><tr><td>f&#39;restorant</td><td>in a restaurant</td><td><code>f&#39;</code> + <code>restorant</code></td></tr><tr><td>ta&#39; lukanda</td><td>of a hotel</td><td><code>lukanda</code> (hotel)</td></tr><tr><td>lussuża</td><td>luxury</td><td>Feminine adjective</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> u għalhekk naħseb li kapaċi għal dan ix-xogħol. Naf nitkellem Ingliż, Malti, u ftit Taljan.</p><p><strong>Translation:</strong> And therefore I think I am capable of this job. I can speak English, Maltese and a little Italian.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>għalhekk</td><td>therefore</td><td><code>għal</code> + <code>hekk</code></td></tr><tr><td>naħseb</td><td>I think</td><td>First-person singular</td></tr><tr><td>li</td><td>that</td><td>Conjunction</td></tr><tr><td>kapaċi</td><td>capable</td><td>Loanword</td></tr><tr><td>għal dan ix-xogħol</td><td>for this job</td><td><code>dan</code> (this) + <code>xogħol</code> (job)</td></tr><tr><td>Naf</td><td>I know; I can</td><td>First-person singular</td></tr><tr><td>nitkellem</td><td>I speak</td><td>First-person singular</td></tr><tr><td>Ingliż</td><td>English</td><td>Language name</td></tr><tr><td>Malti</td><td>Maltese</td><td>Language name</td></tr><tr><td>ftit</td><td>a little</td><td>Quantifier</td></tr><tr><td>Taljan</td><td>Italian</td><td>Language name</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qrajt din l-ittra. Napprezza jekk tikkunsidrani għal dan ix-xogħol.</p><p><strong>Translation:</strong> Thank you for reading this letter. I would appreciate it if you considered me for this job.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite expression</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qrajt</td><td>you read</td><td>Second-person singular past of <code>qara</code></td></tr><tr><td>din l-ittra</td><td>this letter</td><td>See above</td></tr><tr><td>Napprezza</td><td>I appreciate</td><td>Loanword</td></tr><tr><td>jekk</td><td>if</td><td>Conditional conjunction</td></tr><tr><td>tikkunsidrani</td><td>you consider me</td><td><code>tikkunsidra</code> + <code>-ni</code> (me)</td></tr><tr><td>għal dan ix-xogħol</td><td>for this job</td><td>See above</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; niltaqa&#39; miegħek biex nikkellmu iktar fid-dettall kuljum mit-8 ta&#39; filgħodu sas-7 ta&#39; filgħaxija. / meta tkun komdu inti.</p><p><strong>Translation:</strong> I can meet you to talk in more detail any day from 8 in the morning until 7 in the evening. / Or whenever you are comfortable.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular</td></tr><tr><td>niltaqa&#39;</td><td>I meet</td><td>First-person singular</td></tr><tr><td>miegħek</td><td>with you</td><td><code>ma&#39;</code> + <code>-ek</code> (you)</td></tr><tr><td>biex</td><td>in order to</td><td>Purpose conjunction</td></tr><tr><td>nikkellmu</td><td>we talk</td><td>First-person plural of <code>kellem</code></td></tr><tr><td>iktar</td><td>more</td><td>Comparative adverb</td></tr><tr><td>fid-dettall</td><td>in detail</td><td>Contracted <code>f&#39;</code> + <code>id-dettall</code></td></tr><tr><td>kuljum</td><td>daily; every day</td><td>Adverb</td></tr><tr><td>mit-8 ta&#39; filgħodu</td><td>from 8 in the morning</td><td>Contracted <code>minn</code> + <code>it-8</code></td></tr><tr><td>sas-7 ta&#39; filgħaxija</td><td>until 7 in the evening</td><td>Contracted <code>sa</code> + <code>is-7</code></td></tr><tr><td>meta</td><td>when</td><td>Time conjunction</td></tr><tr><td>tkun komdu</td><td>you are comfortable</td><td><code>tkun</code> (are) + <code>komdu</code> (comfortable)</td></tr><tr><td>inti</td><td>you</td><td>Second-person pronoun</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Tisjiet,</p><p><strong>Translation:</strong> Regards, (formal email closing)</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tisjiet</td><td>regards</td><td>As printed in the source; the standard formal spelling is <code>Tislijiet</code></td></tr></tbody></table><p><strong>Malti:</strong> John Mallia</p><p><strong>Translation:</strong> John Mallia (example signature)</p>',61),n=[o];function i(l,s,h,c,p,g){return d(),e("div",null,n)}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
